mapper.select:
SELECT sp.id AS id, sp.story_id AS storyId, s.title AS storyTitle, s.user_id AS ownerUserId, COALESCE(NULLIF(u.realname, ''), u.username) AS ownerDisplayName, sp.channel_code AS channelCode, c.channel_name AS channelName, sp.status AS status, sp.display_title AS displayTitle, sp.display_subtitle AS displaySubtitle, sp.cover_image_url AS coverImageUrl, sp.intro_text AS introText, sp.sort_order AS sortOrder, sp.published_at AS publishedAt, sp.offline_at AS offlineAt, sp.reject_reason AS rejectReason, sp.ext_json AS extJson, sp.create_time AS createTime, sp.update_time AS updateTime FROM ts_story_public sp INNER JOIN ts_story_info s ON s.id = sp.story_id LEFT JOIN ts_public_channel c ON c.channel_code = sp.channel_code LEFT JOIN sys_user u ON u.id = s.user_id WHERE s.is_deleted = 0 AND (s.status IS NULL OR s.status != 9)
AND ( s.title LIKE CONCAT('%', #{query.keyword}, '%') OR sp.display_title LIKE CONCAT('%', #{query.keyword}, '%') OR sp.intro_text LIKE CONCAT('%', #{query.keyword}, '%') )
AND sp.channel_code = #{query.channelCode}
AND sp.status = #{query.status}
AND s.user_id = #{query.ownerUserId}
ORDER BY sp.sort_order ASC, sp.update_time DESC, sp.id DESC

SELECT s.id AS id, sp.id AS publicId, sp.channel_code AS channelCode, COALESCE(NULLIF(sp.display_title, ''), s.title) AS title, sp.display_subtitle AS displaySubtitle, COALESCE(NULLIF(sp.intro_text, ''), s.story_intro) AS storyIntro, s.story_mode AS storyMode, s.scene_image_url AS sceneImageUrl, COALESCE(NULLIF(sp.cover_image_url, ''), s.cover_url) AS coverUrl, COALESCE(st.follower_count, 0) AS followerCount, COALESCE(st.dialogue_count, 0) AS dialogueCount, COALESCE(NULLIF(u.realname, ''), u.username) AS authorName, u.avatar AS authorAvatar, s.updated_at AS updatedAt FROM ts_story_public sp INNER JOIN ts_story_info s ON s.id = sp.story_id LEFT JOIN ts_story_stat st ON st.story_id = s.id LEFT JOIN sys_user u ON u.id = s.user_id WHERE sp.status = 'online' AND s.is_deleted = 0 AND (s.status IS NULL OR s.status != 9)
AND sp.channel_code = #{query.channelCode}
AND ( s.title LIKE CONCAT('%', #{query.keyword}, '%') OR s.story_intro LIKE CONCAT('%', #{query.keyword}, '%') OR sp.display_title LIKE CONCAT('%', #{query.keyword}, '%') OR sp.intro_text LIKE CONCAT('%', #{query.keyword}, '%') )
AND s.story_mode = #{query.storyMode}
ORDER BY sp.sort_order ASC, sp.published_at DESC, sp.id DESC

SELECT s.id AS id, sp.id AS publicId, sp.channel_code AS channelCode, COALESCE(NULLIF(sp.display_title, ''), s.title) AS title, sp.display_subtitle AS displaySubtitle, COALESCE(NULLIF(sp.intro_text, ''), s.story_intro) AS storyIntro, s.story_mode AS storyMode, s.scene_image_url AS sceneImageUrl, COALESCE(NULLIF(sp.cover_image_url, ''), s.cover_url) AS coverUrl, COALESCE(st.follower_count, 0) AS followerCount, COALESCE(st.dialogue_count, 0) AS dialogueCount, COALESCE(NULLIF(u.realname, ''), u.username) AS authorName, u.avatar AS authorAvatar, s.updated_at AS updatedAt FROM ts_story_public sp INNER JOIN ts_story_info s ON s.id = sp.story_id LEFT JOIN ts_story_stat st ON st.story_id = s.id LEFT JOIN sys_user u ON u.id = s.user_id WHERE sp.status = 'online' AND s.is_deleted = 0 AND (s.status IS NULL OR s.status != 9)
AND s.id = #{id}
AND sp.id = #{publicId}
AND sp.channel_code = #{channelCode}
ORDER BY sp.published_at DESC, sp.id DESC LIMIT 1
